-- ExprChecker:123
function ExprChecker.check_member(self, node, scope)
    -- ExprChecker:124
    local object = node:child("object")
    -- ExprChecker:125
    if object.kind == "SelfExpr" then
        -- ExprChecker:126
        local field = node:child("field")
