        end
    end
end
-- Schematic:66
function Schematic.collect_property(stmt, properties, source)
    -- Schematic:67
    local visibility = Option.unwrap_or(stmt:attr("visibility"), "")
    -- Schematic:68
    local is_static = Option.unwrap_or(stmt:attr("is_static"), false)
    -- Schematic:69
